    if (video1 == null) {
        return false;
    }

    return video1.equals(video2);
}

public static boolean isEmpty(Video video) {
    return video == null || video.videoId == null;
}

public int getId() {
    if (id == 0 || id == -1) {
        id = hashCode();
    }

    return id;

